	@Test
	void aliasSpillHasAggregateProcessBudgetAndReleasesOnClose() {
		String property = "org.eclipse.rdf4j.query.bnodeAliasSpill.maxBytes";
		String previous = System.getProperty(property);
		long baseline = BoundedStringMap.diskBytesInUse();
		System.setProperty(property, Long.toString(baseline + 250_000));
		try (var first = new BoundedStringMap(); var second = new BoundedStringMap()) {
			for (int index = 0; index < 5_000; index++) {
				first.putIfAbsent("reserved-" + index, "");
			}
			assertThatThrownBy(() -> {
				for (int index = 0; index < 5_000; index++) {
					second.putIfAbsent("other-" + index, "");
				}
			}).isInstanceOf(QueryEvaluationException.class).hasMessageContaining("disk");
			first.close();
			for (int index = 0; index < 5_000; index++) {
				second.putIfAbsent("other-" + index, "");
			}
			assertThat(second.get("other-4999")).isEmpty();
			second.close();
			assertThat(BoundedStringMap.diskBytesInUse()).isLessThanOrEqualTo(baseline);
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	@Test
	void nestedEvaluationSharesReservationSnapshotWithoutCopyingSpill() throws IOException {
		Set<Path> before = spillFiles();
		var parent = new BlankNodeAllocationScope();
		for (int index = 0; index < 5_000; index++) {
			parent.reserveKnownID("reserved-" + index);
		}
		Set<Path> afterParent = spillFiles();
		assertThat(afterParent).hasSizeGreaterThan(before.size());
		var child = parent.newEvaluationScope();
		assertThat(spillFiles()).containsExactlyInAnyOrderElementsOf(afterParent);
		parent.reserveKnownID("later-parent-only");
		assertThat(child.createBNode(new SimpleValueFactory() {
			@Override
			public BNode createBNode() {
				return createBNode("later-parent-only");
			}
		})).isNotNull();
		parent.close();
		Set<Path> inherited = afterParent.stream().filter(path -> !before.contains(path)).collect(Collectors.toSet());
		assertThat(spillFiles()).containsAll(inherited);
		assertThatThrownBy(() -> child.createBNode(new SimpleValueFactory() {
			@Override
			public BNode createBNode() {
				return createBNode("reserved-4999");
			}
		})).isInstanceOf(QueryEvaluationException.class).hasMessageContaining("fresh");
		child.close();
		assertThat(spillFiles()).doesNotContainAnyElementsOf(inherited);
	}

	@Test
	void repeatedNestedForksReleaseSharedSpillsAfterOutOfOrderClose() {
		long baseline = BoundedStringMap.diskBytesInUse();
		List<BoundedStringMap> scopes = new ArrayList<>();
		try {
			BoundedStringMap root = new BoundedStringMap();
			scopes.add(root);
			for (int index = 0; index < 5_000; index++) {
				root.putIfAbsent("root-" + index, "");
			}
			for (int depth = 0; depth < 5; depth++) {
				BoundedStringMap child = scopes.get(scopes.size() - 1).fork();
				scopes.add(child);
				for (int index = 0; index < 5_000; index++) {
					child.putIfAbsent("depth-" + depth + "-" + index, "");
				}
				assertThat(child.get("root-4999")).isEmpty();
			}
			BoundedStringMap deepest = scopes.get(5);
			assertThat(BoundedStringMap.diskBytesInUse()).isGreaterThan(baseline);
			for (int index : List.of(0, 2, 1, 4, 3)) {
				scopes.get(index).close();
				assertThat(deepest.get("root-4999")).isEmpty();
				assertThat(deepest.get("depth-0-4999")).isEmpty();
			}
			deepest.close();
			assertThat(BoundedStringMap.diskBytesInUse()).isLessThanOrEqualTo(baseline);
		} finally {
			for (BoundedStringMap scope : scopes) {
				scope.close();
			}
		}
	}

	@Test
	void responseScopeExplicitCloseDeletesItsSpill() throws Exception {
		var allocation = new BlankNodeAllocationScope();
		var response = RemoteBNode.newResponseScope(allocation, VF, new Object(), false);
		Set<Path> before = spillFiles();
		for (int index = 0; index < 5_000; index++) {
			response.map(VF.createBNode("remote-" + index));
		}
		Set<Path> created = spillFiles();
		created.removeAll(before);
		assertThat(created).isNotEmpty();
		assertThat(response).isInstanceOf(AutoCloseable.class);
		((AutoCloseable) (Object) response).close();
		Set<Path> remaining = spillFiles();
		remaining.retainAll(created);
		assertThat(remaining).hasSizeLessThan(created.size());
		allocation.close();
		assertThat(spillFiles()).doesNotContainAnyElementsOf(created);
	}

	private static Set<Path> spillFiles() throws IOException {
		Path probe = Files.createTempFile("rdf4j-bnode-probe-", ".tmp");
		Path directory = probe.getParent();
		Files.delete(probe);
		try (Stream<Path> paths = Files.list(directory)) {
			return paths.filter(path -> path.getFileName().toString().startsWith("rdf4j-bnode-alias-"))
					.collect(Collectors.toSet());
		}
	}

	private static long usedHeap() {
		return Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
	}
